"""payments: charges orders. POST /admin/faults injects errors and latency for the labs."""

import asyncio
import random
import uuid

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

from telemetry import setup

app = FastAPI(title="payments")
log = setup(app, "payments")
faults = {"failure_rate": 0.0, "extra_latency_seconds": 0.0}


class Charge(BaseModel):
    order_id: str
    amount: float


class Faults(BaseModel):
    failure_rate: float = 0.0
    extra_latency_seconds: float = 0.0


@app.get("/healthz")
def healthz():
    return {"status": "ok"}


@app.post("/charge")
async def charge(req: Charge):
    await asyncio.sleep(0.02 + random.uniform(0, 0.03) + faults["extra_latency_seconds"])
    if random.random() < faults["failure_rate"]:
        log.warning("payment provider unavailable", extra={"fields": {"order_id": req.order_id}})
        raise HTTPException(status_code=503, detail="payment provider unavailable")
    payment_id = f"pay-{uuid.uuid4().hex[:8]}"
    log.info("payment charged", extra={"fields": {"order_id": req.order_id, "amount": req.amount}})
    return {"payment_id": payment_id, "status": "charged"}


@app.post("/admin/faults")
def set_faults(new: Faults):
    faults.update(new.model_dump())
    log.warning("faults changed", extra={"fields": dict(faults)})
    return faults

